package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct {
	LrAcct      string          // PIC X(6) @0 len=6
	LrPrincipal decimal.Decimal // PIC 9(7)V99 @6 len=9
	LrRate      decimal.Decimal // PIC 9(2)V99 @15 len=4
	LrYears     int64           // PIC 9(2) @19 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                       // PIC X len=1 = "N"
var WsInterest decimal.Decimal = decimal.New(0, 0) // PIC 9(9)V99
var WsTotal decimal.Decimal = decimal.New(0, 0)    // PIC 9(11)V99
var WsCount int64 = 0                              // PIC 9(5)
var WsPrinEd string // PIC Z,ZZZ,ZZ9.99 len=12
var WsIntEd string  // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsTotalEd string // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var loanRec LoanRec

var loanLines []string
var loanIdx int
var loanOpen bool

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func parseDigitsToInt64(s string) int64 {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else if c == ' ' {
			n = n * 10
		} else {
			n = n * 10
		}
	}
	return n
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func formatCount(v int64) string {
	m := v % 100000
	if m < 0 {
		m += 100000
	}
	return fmt.Sprintf("%05d", m)
}

// generic edited formatting
func formatEdited(val decimal.Decimal, picture string) string {
	// count int slots and dec slots
	dotPos := strings.Index(picture, ".")
	var intPic, decPic string
	if dotPos >= 0 {
		intPic = picture[:dotPos]
		decPic = picture[dotPos+1:]
	} else {
		intPic = picture
		decPic = ""
	}
	intSlots := 0
	for i := 0; i < len(intPic); i++ {
		if intPic[i] == 'Z' || intPic[i] == '9' {
			intSlots++
		}
	}
	decSlots := 0
	for i := 0; i < len(decPic); i++ {
		if decPic[i] == 'Z' || decPic[i] == '9' {
			decSlots++
		}
	}
	// truncate toward zero to decSlots
	v := val.Truncate(int32(decSlots))
	neg := v.IsNegative()
	if neg {
		v = v.Neg()
	}
	scaled := v.Shift(int32(decSlots)).IntPart()
	// keep low-order digits that fit: mod 10^(intSlots+decSlots)
	mod := int64(1)
	for i := 0; i < intSlots+decSlots; i++ {
		mod *= 10
	}
	// mod may overflow for large? here max 10^13 fits
	if mod != 0 {
		scaled = scaled % mod
		if scaled < 0 {
			scaled += mod
		}
	}
	pow10dec := int64(1)
	for i := 0; i < decSlots; i++ {
		pow10dec *= 10
	}
	intPart := int64(0)
	fracPart := int64(0)
	if decSlots > 0 {
		intPart = scaled / pow10dec
		fracPart = scaled % pow10dec
	} else {
		intPart = scaled
	}
	// integer digits string padded
	intDigits := make([]byte, intSlots)
	tmp := intPart
	for i := intSlots - 1; i >= 0; i-- {
		intDigits[i] = byte('0' + tmp%10)
		tmp /= 10
	}
	fracDigits := make([]byte, decSlots)
	tmp = fracPart
	for i := decSlots - 1; i >= 0; i-- {
		fracDigits[i] = byte('0' + tmp%10)
		tmp /= 10
	}
	// build output
	var out []byte
	// integer part of picture (including commas)
	digitIdx := 0
	// determine suppression: find first non-zero among intDigits
	firstNZ := -1
	for i := 0; i < intSlots; i++ {
		if intDigits[i] != '0' {
			firstNZ = i
			break
		}
	}
	suppressed := true
	if firstNZ == -1 {
		// all zero: remain suppressed until the 9 slot
		suppressed = true
	} else {
		suppressed = true // will clear when we reach firstNZ
	}
	_ = suppressed
	// iterate over intPic chars
	sup := true
	for pi := 0; pi < len(intPic); pi++ {
		ch := intPic[pi]
		if ch == 'Z' || ch == '9' {
			d := intDigits[digitIdx]
			isLastIntDigit := digitIdx == intSlots-1
			_ = isLastIntDigit
			if ch == 'Z' {
				if sup && d == '0' {
					// check if there is any non-zero later? if all remaining zero, keep space
					// but if this is... Z with zero in suppressed zone => space
					// However if all digits zero, the Z's are spaces (correct)
					out = append(out, ' ')
					// remain sup unless this was last? Z never clears sup on zero
				} else {
					// print digit
					out = append(out, d)
					sup = false
				}
				// if d != '0' and sup, this digit is first non-zero -> clear sup
				if d != '0' {
					sup = false
				}
			} else { // '9'
				out = append(out, d)
				sup = false
			}
			digitIdx++
		} else if ch == ',' {
			if sup {
				out = append(out, ' ')
			} else {
				out = append(out, ',')
			}
		} else {
			out = append(out, ch)
		}
	}
	if dotPos >= 0 {
		out = append(out, '.')
		fIdx := 0
		for pi := 0; pi < len(decPic); pi++ {
			ch := decPic[pi]
			if ch == 'Z' || ch == '9' {
				out = append(out, fracDigits[fIdx])
				fIdx++
			} else {
				out = append(out, ch)
			}
		}
	}
	_ = neg // values are unsigned (non-negative) in this program
	return string(out)
}

func storePic9V99(v decimal.Decimal, intDigits int) decimal.Decimal {
	// round/truncate already done by caller; here keep low-order digits
	r := v.Truncate(2)
	neg := r.IsNegative()
	abs := r
	if neg {
		abs = r.Neg()
	}
	scaled := abs.Shift(2).IntPart()
	mod := int64(1)
	for i := 0; i < intDigits+2; i++ {
		mod *= 10
	}
	scaled = scaled % mod
	res := decimal.New(scaled, -2)
	if neg {
		// for unsigned field, COBOL would... keep magnitude with sign? not needed
		res = res.Neg()
	}
	return res
}

func openLoanFile() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	content := string(data)
	if len(content) == 0 {
		loanLines = []string{}
		loanIdx = 0
		loanOpen = true
		return
	}
	parts := strings.Split(content, "\n")
	// if content ends with newline, last part is artifact
	if strings.HasSuffix(content, "\n") {
		parts = parts[:len(parts)-1]
	}
	// strip trailing \r (CRLF)
	for i := range parts {
		if len(parts[i]) > 0 && parts[i][len(parts[i])-1] == '\r' {
			parts[i] = parts[i][:len(parts[i])-1]
		}
	}
	loanLines = parts
	loanIdx = 0
	loanOpen = true
}

func MAINPARA() {
	openLoanFile()
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	loanOpen = false
	SUMMARYPARA()
}

func READPARA() {
	if !loanOpen {
		WsEofFlag = "Y"
		return
	}
	if loanIdx >= len(loanLines) {
		WsEofFlag = "Y"
		return
	}
	line := loanLines[loanIdx]
	loanIdx++
	rec := padRight(line, 21)
	if len(rec) > 21 {
		rec = rec[:21]
	}
	loanRec.LrAcct = rec[0:6]
	nPrin := parseDigitsToInt64(rec[6 : 6+9])
	loanRec.LrPrincipal = decimal.New(nPrin, -2)
	nRate := parseDigitsToInt64(rec[15 : 15+4])
	loanRec.LrRate = decimal.New(nRate, -2)
	loanRec.LrYears = parseDigitsToInt64(rec[19 : 19+2])
}

func PROCESSPARA() {
	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	prod := loanRec.LrPrincipal.Mul(loanRec.LrRate).Mul(decimal.NewFromInt(loanRec.LrYears))
	exact := prod.Shift(-2)
	rounded := exact.Round(2)
	WsInterest = storePic9V99(rounded, 9)
	// ADD WS-INTEREST TO WS-TOTAL
	WsTotal = storePic9V99(WsTotal.Add(WsInterest), 11)
	// ADD 1 TO WS-COUNT
	WsCount = (WsCount + 1) % 100000
	// MOVEs
	WsPrinEd = formatEdited(loanRec.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")
	fmt.Println(loanRec.LrAcct+" "+WsPrinEd+" "+WsIntEd)
	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	fmt.Println("RECORDS: "+formatCount(WsCount))
	fmt.Println("TOTAL INTEREST: "+WsTotalEd)
}

func main() {
	WsEofFlag = "N"
	WsInterest = decimal.New(0, 0)
	WsTotal = decimal.New(0, 0)
	WsCount = 0
	MAINPARA()
}
